INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 945, 0, 7, 11, 122611, 19450024, 0, 1, 0, "買い出しまで手伝ってもらったのに\nごめんね。でも、お弁当の中身、\nちょっと張り切りすぎちゃって…");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", 945, "", "", 91, 0, 19450025, "", "", "", "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 945, "", "", 21, "vo_fpc", 19450026, "", "", "", "vo_fpc_30503");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (1, 945, 0, 7, 11, 110411, 19450027, 0, 1, 0, "なんだよ、張り切りすぎちゃったって。\n用意してた材料は普通だったろ？\nん？　そういやあピンクの桜でんぶ\n買ってたよな。まさか…");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", 945, "", "", 91, 0, 19450028, "", "", "", "");
